// ***************
// Filename: feature_detect_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of feature_detect: joins the register map
//   feature_detect_regs (modport regs) and the logic feature_detect (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   feature_detect_regs.json: edit the JSON and regenerate.
// Date: 2026-10-21
interface feature_detect_regs_if ();
  logic [32-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [32-1:0] cfg_frame_size;
  logic cfg_frame_size_wr;
  logic [32-1:0] cfg_edge;
  logic cfg_edge_wr;
  logic [32-1:0] cfg_motion;
  logic cfg_motion_wr;
  logic [32-1:0] cfg_shift;
  logic cfg_shift_wr;
  logic [32-1:0] sts_shift_est;
  logic [32-1:0] sts_status;
  logic [32-1:0] sts_frames;
  logic [32-1:0] sts_edge_count;
  logic [32-1:0] sts_motion_count;
  logic [32-1:0] sts_shift_used;
  logic [16-1:0] cfg_sky_cfg;
  logic cfg_sky_cfg_wr;
  logic [(32)*(16)-1:0] sts_sky;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr, cfg_edge, cfg_edge_wr,
    cfg_motion, cfg_motion_wr, cfg_shift, cfg_shift_wr, cfg_sky_cfg, cfg_sky_cfg_wr, input sts_shift_est,
    sts_status, sts_frames, sts_edge_count, sts_motion_count, sts_shift_used, sts_sky);
  modport core (output sts_shift_est, sts_status, sts_frames, sts_edge_count, sts_motion_count,
    sts_shift_used, sts_sky, input cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr, cfg_edge,
    cfg_edge_wr, cfg_motion, cfg_motion_wr, cfg_shift, cfg_shift_wr, cfg_sky_cfg, cfg_sky_cfg_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr, cfg_edge, cfg_edge_wr,
    cfg_motion, cfg_motion_wr, cfg_shift, cfg_shift_wr, cfg_sky_cfg, cfg_sky_cfg_wr, sts_shift_est,
    sts_status, sts_frames, sts_edge_count, sts_motion_count, sts_shift_used, sts_sky);
endinterface
